                C3DVector out_line = int_pos - AxisBottom;
                float height_param = out_line.Dot(cyl_ax) / (cyl_height * cyl_height);
                if (height_param > -DELTA_NOTIONAL_ZERO && height_param < 1.0f + DELTA_NOTIONAL_ZERO) {
